"""Render the final decision directly from measured, clustered results."""
import collections,hashlib,json,pathlib,statistics
ROOT=pathlib.Path(__file__).resolve().parents[1];OUT=ROOT/'outputs'
def read(name):return json.loads((OUT/name).read_text(encoding='utf8'))
def ci(v):
    if v['mean'] is None:return 'NA (no eligible clusters)'
    return f"{v['mean']:.5f} [{v['ci95'][0]:.5f}, {v['ci95'][1]:.5f}]; pairs={v['n_pairs']}, groups={v['n_clusters']}"
def table(headers,rows):return '\n'.join(['| '+' | '.join(headers)+' |','| '+' | '.join(['---']*len(headers))+' |']+['| '+' | '.join(map(str,r))+' |' for r in rows])
def positive(v,minimum=0):return v['mean'] is not None and v['ci95'][0]>minimum

def main():
    analysis=read('analysis_audit_aligned.json');original=read('analysis_audit.json');dev=read('analysis_dev.json');rename=read('analysis_rename_aligned.json')
    baseline=read('baseline_results.json');profile=read('runtime_profile.json');preflight=read('preflight_native.json');env=read('environment.json')
    manifest=[json.loads(s) for s in (OUT/'sample_manifest.jsonl').read_text(encoding='utf8').splitlines()]
    records=[json.loads(s) for s in (OUT/'intervention_results.jsonl').read_text(encoding='utf8').splitlines()]
    data=read('data_audit_tokenized.json');threshold=analysis['thresholds']['local_small_threshold_nats']
    datasets=['nestful_v2_math','controlled_symbol_chains_new_diagnostic'];short={'nestful_v2_math':'NESTFUL binding','controlled_symbol_chains_new_diagnostic':'Controlled states'}
    from analyze_results import estimate,paired_depth
    base_index={(r['parent_id'],r['H']):r for r in analysis['cases'] if r['kind']=='dependent' and r['dataset']==datasets[1]}
    rename_delta=[{'parent_id':r['parent_id'],'delta':r['G_source']-base_index[(r['parent_id'],r['H'])]['G_source']} for r in rename['cases'] if r['kind']=='dependent']
    gates={}
    for ds in datasets:
        a=analysis['statistics'][ds]['dependent']['all'];matched=analysis['dependency_matched_comparisons'][ds]['all']
        key=analysis['statistics'][ds]['dependent']['native_source_K1_and_low_local']['G_source']
        gates[ds]={'positive_source_gt_0p01_nats':positive(a['G_source'],.01),'dependency_specific':positive(matched),
                   'positive_mask_attenuation':positive(a['mask_attenuation']),'native_K1_low_local_positive':positive(key,.01)}
    tails=[]
    for ds in datasets:
        values=[r for r in analysis['cases'] if r['kind']=='dependent' and r['dataset']==ds]
        eligible=[r for r in values if r['native_source_depth']==1 and r['low_local']]
        tails.append([short[ds],sum(r['G_source']>.01 for r in values),sum(r['G_source']<-.01 for r in values),len(eligible),sum(r['G_source']>.01 for r in eligible)])
    gate=any(all(g.values()) for g in gates.values())
    serving=preflight['official_serving_equivalence_verified'];pilot_success=any(s['full_task_success_rate']>0 for s in baseline['summaries'] if s['dataset']=='all')
    # Positive data are necessary, not sufficient, for a GO decision. Infrastructure
    # and task identifiability prevent an unconditional rejection of H1/H2 here.
    decision='INCONCLUSIVE'
    status={'decision':decision,'stage4_positive_evidence_gate_passed':gate,'gates_by_dataset':gates,
            'official_serving_equivalence_verified':serving,'primary_pilot_has_full_task_success':pilot_success,
            'stage4_executed':False,'stage4_reason':'No reliable positive dependency-specific delayed benefit in the low-local/native-K1 target stratum; no allocation-gain claim.',
            'scope':'No GO_H2 or GO_H1_ONLY justified; narrow negative evidence does not establish H0 for general long-horizon reasoning.'}
    (OUT/'research_decision.json').write_text(json.dumps(status,indent=2),encoding='utf8')
    report=['# FINAL REPORT — Long-Horizon Loop Dependency Audit v1',
            '',f'**Final decision: `{decision}`.** Stage 0 native baselines, Stage 1 interfaces, and Stage 2–3 fixed-text interventions were executed. The official serving engine remains unverified on Windows. Stage 4 was not opened because its positive-evidence gate did not pass.',
            '', '## A. Reproduction & Infrastructure','',
            f"Official TaH commit: `78ddf9a2c25713fced03a736c5746161f6ee590c`. Max2 HF revision: `e965dff2bd539b5be8087126b7d26bcb47e1b159`; independently trained Standard: `bbf0d82946c8e242ab2dc1f3be20408e317562ec`. NESTFUL commit: `fc2c4123e73500a56185a5fb354f05d1c8b4890c`.",
            '',f"GPU: {env['gpu']}; CUDA runtime {env['cuda']}; Python {env['python'].split()[0]}; BF16, batch1, seed42. Versions: `{json.dumps(env['versions'],sort_keys=True)}`. Complete package/model-file hashes are in execution_provenance.json and source_metadata/.",
            '', 'The host is Windows without installed WSL/Docker. The official extra cannot resolve a Windows Triton wheel. After portable imports were installed, the actual official smoke test reached `makeDeviceForHostname(): unsupported gloo device`. No engine source or model weights were patched to bypass this. The mechanism backend uses the pinned official tah2/model path with only its attention implementation changed to native SDPA. This does not meet the required empirical mini-SGLang parity check.',
            '',f"No-intervention native/wrapper difference: {preflight['checks']['no_intervention_native_wrapper_max_logit_difference']}. Repeats, causal isolation, branch independence and native probability-mixture reconstruction are recorded in preflight_native.json. Weight hash before/after: `{preflight['weights_hash_after']}`.",
            '', 'Full-prefill/incremental BF16 outputs are numerically close under the declared tolerance, not bitwise equal. Full-vocabulary log-probability max differences were 0.4375/0.5 nats at K1/K2; target-CE and top1 checks are recorded separately. Broad full-vocabulary tolerance alone is not evidence that a 0.01-nat mechanism effect is reliable.',
            '', 'A development-only layout null revealed nontrivial numerical effects: its 95th percentile absolute deviation was 0.06250 nats and maximum 0.07267 nats. The complete matched audit was therefore also run with an invalid, zero deep-cache slot in K1 branches. Original results remain intact. See NUMERIC_REPAIR.md.',
            '',f"Final aligned source-K2/consumer-K1 null maximum: {analysis['source_K2_consumer_K1_max_abs_effect']:.9g} nats; I minus G_source maximum: {analysis['identity_max_abs_I_minus_G_source']:.9g} nats.",
            '',f"Tracked CUDA-synchronized forward/generation wall time: {profile['cuda_seconds_so_far']:.1f}s ({profile['cuda_seconds_so_far']/3600:.3f}h). This includes CPU observer work inside forwards and is not a kernel-only GPU utilization measurement. Setup, transfers, model hashing and raw-logit compression are separate. An aborted initial masking call and preflight repetitions are noted as additional unaggregated short runs; this total is a tracked lower bound, not a fictitious exact resource bill. The 8h soft cap was not reached.",
            '', 'Real pilot cost predicted the audit well: original development used 83.06s of measured forwards for 96 dependent pairs plus controls; the original audit used 223.34s for 253 dependent pairs plus controls. Prefixes were reused. Per-branch wall times, actual loop counts, cache depths, peak allocation and a parameter-matmul FLOPs proxy are preserved. The FLOPs proxy excludes attention/context and is not used for fairness claims.',
            '', '## B. Baseline Results','', 'These are the same 20 development prompts, 512 maximum output tokens, greedy native generation, thinking disabled. Standard uses different weights; the other three use identical max2 weights. Loop averages include all actually executed prompt/decode positions.', '',
            table(['Method','N','Parse','Executable','Full task','Mean depth','Generated tokens','Wall s','Peak MiB'],[[s['method'],s['n'],f"{s['format_success_rate']:.0%}",f"{s['execution_success_rate']:.0%}",f"{s['full_task_success_rate']:.0%}",f"{s['mean_actual_depth']:.3f}",s['generated_tokens'],f"{s['seconds']:.1f}",f"{s['peak_cuda_allocated_mib']:.1f}"] for s in baseline['summaries'] if s['dataset']=='all']),
            '', 'A parsed controlled state array counts as executable output, even when its values are wrong. NESTFUL execution uses actual official functions and typed final-value equality. Unquoted variable references are rejected as invalid JSON rather than silently repaired. These results describe this prompt/output-budget protocol; they do not prove that the checkpoint cannot reason with longer outputs or a different agent interface. Correct-intermediate rates and first errors are available in baseline_pilot_records.jsonl.',
            '', '## C. Local vs Delayed Benefit','',f'Local-small threshold: {threshold:.5f} nats, frozen on development only. Primary numbers below use cache-aligned replay. Confidence intervals use 5000 seed42 resamples of original problems/matched groups, equal weight per parent. They are descriptive and are not multiplicity-adjusted.', '',
            table(['Dataset','G_local anchor','G_local full source unit','G_source delayed','G_source complete consumer span'],[[short[ds]]+[ci(analysis['statistics'][ds]['dependent']['all'][k]) for k in ['G_local','G_local_unit','G_source','G_source_span']] for ds in datasets]),
            '', table(['Dataset','Pairs with gain >0.01','Pairs with gain <-0.01','Native-K1/low-local pairs','Positive eligible pairs'],tails),
            '', 'There are positive individual counterfactuals. Their presence is not hidden by the negative/uncertain mean. Selecting those audit cases retrospectively is an oracle, not evidence that an online policy can predict their benefit or that they have semantic dependency specificity.',
            '',table(['Dataset / stratum','Delayed source gain, 95% CI and actual N'],[[short[ds]+' / '+view,ci(analysis['statistics'][ds]['dependent'][view]['G_source'])] for ds in datasets for view in ['native_source_K1','low_local_abs_gain','native_source_K1_and_low_local']]),
            '',f"Continuous problem-mean associations: `{json.dumps(analysis['continuous_local_vs_delayed'],sort_keys=True)}`. Correlation is descriptive; no independence or mediation conclusion follows from it. Raw per-loop source CE and the full source-unit metric are also provided. A low mixture-CE gain is not automatically evidence of an unchanged deep representation.",
            '', '![Local versus delayed gain](figures/audit_aligned/local_vs_delayed.png)',
            '', '## D. Producer–Consumer Interaction','',
            table(['Dataset','U11','U21','U12','U22'],[[short[ds]]+[ci(analysis['statistics'][ds]['dependent']['all']['U'+c]) for c in ['11','21','12','22']] for ds in datasets]),
            '',table(['Dataset','G_source','G_consumer','I'],[[short[ds]]+[ci(analysis['statistics'][ds]['dependent']['all'][k]) for k in ['G_source','G_consumer','I']] for ds in datasets]),
            '', 'At the single target anchor, DUO forbids the K1 consumer from seeing a K2 producer. Thus U21=U11 and I=G_source. This observed identity is an architecture check, not independent evidence for coordinated allocation. Complete consumer-span utilities are supplementary and may include other frozen K2 positions; the identity is not extended to them.',
            '', '## E. Mechanism Controls','',
            table(['Dataset','Dependent minus matched nondependent','Deep-KV masking attenuation','Deep minus shallow substitution','Masked-layout null'],[[short[ds],ci(analysis['dependency_matched_comparisons'][ds]['all'])]+[ci(analysis['statistics'][ds]['dependent']['all'][k]) for k in ['mask_attenuation','shallow_gap','masked_shape_null']] for ds in datasets]),
            '', 'Controls match output-token event role, native source depth and a half-to-double token-distance bound, then rank distance/local native-CE differences. They do not enforce identical operator type or identical graph-position role; matching is coarse and its distances/difficulty differences are saved. Their absolute loop budgets are asserted equal. Sparse NESTFUL control availability limits specificity claims; no control is fabricated for H16, where every earlier state is an ancestor. All missing-control reasons are recorded in core_runtime_*.json.',
            '', 'A positive deep-versus-shallow gap alone can mean that duplicated shallow memory is harmful. It does not show that adding deep memory is better than K1. Likewise, KV masking can establish access dependence only when it attenuates a real positive semantic benefit. Neither result alone establishes a long-horizon allocation advantage.',
            '', 'In the aligned layout, masked K2 source memory and the K1 padded source are observationally equivalent. Therefore the masking attenuation reduces to G_source when that strict null passes. Together with I=G_source, these are overlapping algebraic contrasts, not three independent confirmations. Dependency specificity and actual task success remain the discriminating evidence.',
            '', '![Mechanism controls](figures/audit_aligned/mechanism_controls.png)',
            '', '## F. Long-Horizon Effects','',
            table(['Controlled depth','Delayed source gain','Consumer gain'],[[f'H={h}',ci(analysis['statistics'][datasets[1]]['dependent'][f'H{h}']['G_source']),ci(analysis['statistics'][datasets[1]]['dependent'][f'H{h}']['G_consumer'])] for h in [4,16]]),
            '', 'Paired H16 minus H4 delayed-source contrast: '+ci(paired_depth(analysis['cases'])['G_source'])+'. This remains a depth/position/distance contrast, not an isolated graph-depth causal effect.',
            '', 'The primary audit contains 64 independent NESTFUL problems and 64 controlled matched groups (128 H4/H16 inputs). It has 253 available dependent pairs: 125 NESTFUL and 128 controlled, hence 1012 primary 2x2 branches per layout. Three NESTFUL problems have only one selected valid pair. H2/H8 use a separate cost-led extension on the already locked 64 groups. They are not promoted to the primary test. Symbol renaming is scored separately on the first 16 locked groups, at both primary depths.',
            '',table(['Renamed controlled stratum','Delayed source gain'],[[view,ci(rename['statistics'][datasets[1]]['dependent'][view]['G_source'])] for view in ['all','H4','H16']]),
            '', 'Matched renamed-minus-base delayed-source contrast on the same 16 groups: '+ci(estimate(rename_delta,'delta'))+'. Original and renamed inputs each retain their own recorded native depth policy, so this is a robustness comparison rather than a pure fixed-policy lexical intervention.',
            '', 'NESTFUL anchors predict the first digit of a variable identifier, with its full reference span also scored. Its labels do not carry numeric tool results; this is a binding probe, not a test of hidden arithmetic-result retention. Controlled anchors predict actual state symbols, but correct intermediate states are teacher-forced. They can screen earlier source information. H changes source location/token distance as well as chain organization, so a depth difference cannot be attributed solely to latent horizon. The source cache entry being deepened is the prediction position before the output value, rather than the position after consuming that value.',
            '', '![Dependency-depth effect](figures/audit_aligned/depth_effect.png)',
            '', '## G. Compute–Performance','',
            f"Positive-evidence gate: `{json.dumps(gates,sort_keys=True)}`. Stage4 random/local-oracle/joint-oracle allocation runs were not executed. No equal-budget task-performance comparison or oracle advantage is claimed. The 512-token baselines have unequal executed compute, and are baseline diagnostics rather than matched-budget evidence.",
            '', '## H. Negative Evidence & Remaining Limits','',
            '- Native original/wrapper equality and cache causal checks do not replace missing serving-engine equivalence.\n- No reliable positive dependency-specific delayed benefit supports a GO decision in the target low-local/native-K1 stratum.\n- Controlled-state sources may have no native-K1 examples; their actual subgroup N is reported above rather than filled in.\n- A 512-token one-shot task protocol yields zero full-task successes in the pilot. Longer-output sensitivity is reported separately if executed.\n- NESTFUL probes bindings and identifier digits; controlled teacher forcing reveals intermediate values. Neither alone identifies general hidden long-range reasoning.\n- The original cache layouts generate numerical effects comparable to small purported benefits. Both layouts are reported and the strict null is checked.\n- H16 lacks a legal nondependent same-role control, while NESTFUL matching coverage is sparse.\n- One seed, one checkpoint family, small independent-group counts and descriptive multiple CIs limit generalization.\n- Deployed agent runs and Stage4 privileged/equal-budget allocations are not executed. No missing result is imputed.',
            '', '## I. Final Research Decision','',
            '**INCONCLUSIVE.** The requested mechanism audit is implemented and actually run, with useful negative evidence for these probes. It does not justify GO_H2 or GO_H1_ONLY. It also does not establish H0 for the broader research question: the official serving parity check, free task capability, semantic source-carrier choice and the main native-K1 state stratum remain limiting. Building a coordinated-recurrence model now would outrun the evidence.',
            '', 'The next decisive experiment should make the source a value-bearing, causally observable state, separate token distance from graph depth, and avoid revealing every relevant mediator through teacher forcing. It must first pass a development capability/eligible-source check. More checkpoints or a new router are not substitutes for that identification step. Prospective method candidates are delivered separately from these public audit records.',
            '', 'Reproduction commands are in README.md; per-phase outputs include locked plans, policies, thresholds, raw branch records, model hashes, aligned and unaligned statistics and figures. See PRIMARY_SOURCES.md for the verified primary literature and upstream licenses.']
    if (OUT/'analysis_depths_aligned.json').exists():
        extension=read('analysis_depths_aligned.json')
        text='\n\n### Locked-manifest H2/H8 extension\n\nMeasured primary replay cost was below the cap, so all 64 existing audit groups were also evaluated at H2 and H8 with cache alignment. This adds 128 dependent pairs / 512 core cells plus controls, without adding independent groups or changing the frozen primary thresholds. These exploratory results do not reopen the primary Stage4 gate.\n\n'+table(['Depth','Delayed source gain','Native K1 source gain'],[[str(h),ci(extension['statistics'][datasets[1]]['dependent'][f'H{h}']['G_source']),ci({**estimate([r for r in extension['cases'] if r['kind']=='dependent' and r['H']==h and r['native_source_depth']==1],'G_source')})] for h in [2,8]])
        report.insert(report.index('## G. Compute–Performance'),text)
    if (OUT/'baseline_length_probe.json').exists():
        probe=read('baseline_length_probe.json')
        text='\n\n### Separate development output-length sensitivity\n\nSame prompts/weights/native SDPA dispatch, max2048 outputs; four deterministically selected development prompts, not the primary 20-prompt comparison. Native workers crashed with 0xC0000005 and 0xC0000409 (Python/UCRT event-log modules). Partial multi-prompt records are retained but excluded from accuracy. Successful isolated prompts have immediate before/after weight validation and durable export before OS process teardown. The remaining worker processes were constrained to the observed lower-efficiency CPU-set class (logical processors 16–31), with no BIOS/voltage/global scheduler or model changes. Earlier validated Standard prompts used the original affinity. Thus latency here is operational diagnostic data, not a fair output-length speed comparison. The crash root cause remains unresolved.\n\n'+table(['Method','N','Parse successes','Full successes','Limit hits','Generated tokens','Wall s'],[[s['method'],s['n'],s['format_successes'],s['full_task_successes'],s['generation_limit_hits'],s['generated_tokens'],f"{s['seconds']:.1f}"] for s in probe['summaries']])
        report.insert(report.index('## C. Local vs Delayed Benefit'),text)
    (OUT/'FINAL_REPORT.md').write_text('\n'.join(report)+'\n',encoding='utf8')
    print(json.dumps(status,indent=2))
if __name__=='__main__':main()
